item.description:
#user  nobody;
user root;
worker_processes  1;

#error_log  logs&#x2F;error.log;
#error_log  logs&#x2F;error.log  notice;
#error_log  logs&#x2F;error.log  info;

#pid        logs&#x2F;nginx.pid;


events &#123;
    worker_connections  1024;
&#125;


http &#123;
    include       mime.types;
    default_type  application&#x2F;octet-stream;
    underscores_in_headers on;
    client_max_body_size 50M;
    server_tokens off;

    #log_format  main  &#39;$remote_addr - $remote_user [$time_local] &quot;$request&quot; &#39;
    #                  &#39;$status $body_bytes_sent &quot;$http_referer&quot; &#39;
    #                  &#39;&quot;$http_user_agent&quot; &quot;$http_x_forwarded_for&quot;&#39;;

    log_format main  &#39;$remote_addr - $remote_user [$time_local] [$msec] [$request_time] [$http_host] &quot;$request&quot; &#39;
                          &#39;$status $body_bytes_sent &quot;$request_body&quot; &quot;$http_referer&quot; &#39;
                          &#39;&quot;$http_user_agent&quot; $http_x_forwarded_for&#39;;

    #access_log  logs&#x2F;access.log  main;

    sendfile        on;
    #tcp_nopush     on;

    #keepalive_timeout  0;
    keepalive_timeout  65;

    gzip on;
    gzip_disable &quot;msie6&quot;;

    gzip_vary on;
    gzip_proxied any;
    gzip_comp_level 6;
    gzip_buffers 16 8k;
    gzip_http_version 1.1;
    gzip_min_length 256;
    gzip_types text&#x2F;plain text&#x2F;css application&#x2F;json application&#x2F;x-javascript text&#x2F;xml application&#x2F;xml application&#x2F;xml+rss text&#x2F;javascript application&#x2F;vnd.ms-fontobject application&#x2F;x-font-ttf font&#x2F;opentype font&#x2F;x-woff image&#x2F;svg+xml image&#x2F;x-icon image&#x2F;jpeg image&#x2F;gif image&#x2F;png;

    fastcgi_connect_timeout 300;
    fastcgi_send_timeout 300;
    fastcgi_read_timeout 300;
    fastcgi_buffer_size 64k;
    fastcgi_buffers 4 64k;
    fastcgi_busy_buffers_size 128k;
    fastcgi_temp_file_write_size 128k;


   upstream webservice&#123;
       server localhost:8080  weight&#x3D;1   max_fails&#x3D;10 fail_timeout&#x3D;40s;
       keepalive 512;
    &#125;
    #定义一个名为allips的limit_req_zone用来存储session，大小是10M内存，
    ##以$binary_remote_addr 为key,限制平均每秒的请求为20个，
    ##1M能存储16000个状态，rete的值必须为整数，
    ##如果限制两秒钟一个请求，可以设置成30r&#x2F;m
    limit_req_zone $binary_remote_addr zone&#x3D;allips:1m rate&#x3D;30r&#x2F;s;
    #定义一个名为one的limit_zone,大小10M内存来存储session，
    ##以$binary_remote_addr 为key
    ##nginx 1.18以后用limit_conn_zone替换了limit_conn
    ##且只能放在http作用域
    limit_conn_zone $binary_remote_addr zone&#x3D;one:1m;

    server &#123;

	listen       80;
        server_name  localhost,genesisx.cn,www.genesisx.cn;

        rewrite ^(.*)$ https:&#x2F;&#x2F;$host$1 permanent;
        break;
        #charset koi8-r;

        #access_log  logs&#x2F;host.access.log  main;

        #location &#x2F; &#123;
        #    root   &#x2F;usr&#x2F;local&#x2F;nginx&#x2F;html;
        #    index  index.html index.htm;
        #&#125;
#        location ^~ &#x2F; &#123;
#            alias   &#x2F;home&#x2F;admin&#x2F;xing&#x2F;dist&#x2F;;
#            index  index.html index.htm;
#	    try_files $uri $uri&#x2F; &#x2F;index.html;
#        &#125;

#	location &#x2F;api &#123;
#	    proxy_pass   http:&#x2F;&#x2F;localhost:8080;
#	    rewrite ^&#x2F;api&#x2F;(.*)$  &#x2F;$1 break;
#	&#125;

    location &#x2F; &#123;
	#限制每ip每秒不超过20个请求，漏桶数burst为5
	##brust的意思就是，如果第1秒、2,3,4秒请求为19个，
	##第5秒的请求为25个是被允许的。
	##但是如果你第1秒就25个请求，第2秒超过20的请求返回503错误。
	##nodelay，如果不设置该选项，严格使用平均速率限制请求数，
	##第1秒25个请求时，5个请求放到第2秒执行，
	##设置nodelay，25个请求将在第1秒执行。
	#
	limit_req zone&#x3D;allips burst&#x3D;5 nodelay;
	limit_conn one 10;          #连接数限制
	limit_conn_log_level error;
	#带宽限制,对单个连接限数，如果一个ip两个连接，就是500x2k
	limit_rate 6144k;

	proxy_set_header        Host $host;
        proxy_set_header        X-Real-IP $remote_addr;
        proxy_set_header        X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header        X-Forwarded-Proto $scheme;
        proxy_pass              http:&#x2F;&#x2F;localhost:8090&#x2F;;
        proxy_read_timeout      360;
    &#125;


	#location &#x2F;login &#123;
        #    rewrite &#x2F;login&#x2F; &#x2F; break;
        #&#125;
        #error_page  404              &#x2F;404.html;

        # redirect server error pages to the static page &#x2F;50x.html
        #
        error_page   500 502 503 504  &#x2F;50x.html;
        location &#x3D; &#x2F;50x.html &#123;
            root   html;
        &#125;

        # proxy the PHP scripts to Apache listening on 127.0.0.1:80
        #
        #location ~ \.php$ &#123;
        #    proxy_pass   http:&#x2F;&#x2F;127.0.0.1;
        #&#125;

        # pass the PHP scripts to FastCGI server listening on 127.0.0.1:9000
        #
        #location ~ \.php$ &#123;
        #    root           html;
        #    fastcgi_pass   127.0.0.1:9000;
        #    fastcgi_index  index.php;
        #    fastcgi_param  SCRIPT_FILENAME  &#x2F;scripts$fastcgi_script_name;
        #    include        fastcgi_params;
        #&#125;

        # deny access to .htaccess files, if Apache&#39;s document root
        # concurs with nginx&#39;s one
        #
        #location ~ &#x2F;\.ht &#123;
        #    deny  all;
        #&#125;
    &#125;


#server &#123;
#    listen       80;
#    server_name  blog.genesisx.cn;
#    location &#x2F; &#123;
#        proxy_set_header        Host $host;
#        proxy_set_header        X-Real-IP $remote_addr;
#        proxy_set_header        X-Forwarded-For $proxy_add_x_forwarded_for;
#        proxy_set_header        X-Forwarded-Proto $scheme;
#        proxy_pass              http:&#x2F;&#x2F;localhost:8090;
#        proxy_read_timeout      360;
#    &#125;
#&#125;

    # another virtual host using mix of IP-, name-, and port-based configuration
    #
    #server &#123;
    #    listen       8000;
    #    listen       somename:8080;
    #    server_name  somename  alias  another.alias;

    #    location &#x2F; &#123;
    #        root   html;
    #        index  index.html index.htm;
    #    &#125;
    #&#125;


    # HTTPS server
    #
    server &#123;
        listen       443 ssl http2;
        server_name localhost,www.genesisx.cn;

        ssl_certificate      &#x2F;root&#x2F;https&#x2F;9743717_www.genesisx.cn.pem;
        ssl_certificate_key  &#x2F;root&#x2F;https&#x2F;9743717_www.genesisx.cn.key;

        ssl_session_cache    shared:SSL:1m;
        ssl_session_timeout  50m;

        #ssl_ciphers  HIGH:!aNULL:!MD5;
        ssl_ciphers ECDHE-RSA-AES256-SHA384:AES256-SHA256:RC4:HIGH:!MD5:!aNULL:!eNULL:!NULL:!DH:!EDH:!AESGCM;
        ssl_prefer_server_ciphers  on;
        ssl_protocols TLSv1.2 TLSv1.3;
        ssl_buffer_size 4k;

        ssl_stapling on;
        ssl_stapling_verify on;
        ssl_trusted_certificate &#x2F;root&#x2F;https&#x2F;9743717_www.genesisx.cn.pem;

        #location &#x2F; &#123;
        #    root   html;
        #    index  index.html index.htm;
        #&#125;
        location &#x2F; &#123;
          proxy_set_header        Host $host;
          proxy_set_header        X-Real-IP $remote_addr;
          proxy_set_header        X-Forwarded-For $proxy_add_x_forwarded_for;
          proxy_set_header        X-Forwarded-Proto $scheme;
          proxy_pass              http:&#x2F;&#x2F;localhost:8090&#x2F;;
          proxy_read_timeout      360;
        &#125;
    &#125;

&#125;
